#!/usr/bin/env node
// The interface texts of every plugin come from one place: i18n/<lang>.json.
// This script writes them where each plugin reads them, checks them, and
// starts a new language.
//
//   node scripts/i18n.mjs            write the generated files (task i18n)
//   node scripts/i18n.mjs --check    fail if a translation is incomplete or a generated file is stale (task i18n:check)
//   node scripts/i18n.mjs --new cs   start i18n/cs.json from English (task i18n:new CODE=cs)
//
// See i18n/README.md for what goes where.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const DIR = path.join(root, "i18n");
const SECTIONS = ["panel", "vscode", "commands", "jetbrains", "neovim", "screenshots"];
const META = ["name", "numberLocale", "decimal", "m", "km"];
const PLURAL_FORMS = ["zero", "one", "two", "few", "many", "other"];
const HEADER = "generated by scripts/i18n.mjs from i18n/*.json: edit those, then run `task i18n`";

// ---------------------------------------------------------------- loading

const isPlural = v => v && typeof v === "object" && !Array.isArray(v) && Object.keys(v).length > 0 && Object.keys(v).every(k => PLURAL_FORMS.includes(k));
const isLang = code => /^[a-z]{2,3}$/.test(code);

/** English first, then the other languages by code. */
function load() {
  const codes = fs.readdirSync(DIR).filter(f => f.endsWith(".json")).map(f => f.slice(0, -5)).filter(isLang);
  if (!codes.includes("en")) throw new Error("i18n/en.json is missing");
  const order = ["en", ...codes.filter(c => c !== "en").sort()];
  const langs = {};
  for (const c of order) langs[c] = JSON.parse(fs.readFileSync(path.join(DIR, c + ".json"), "utf8"));
  return { order, langs };
}

// ---------------------------------------------------------------- checks

/** The plural forms a language really uses for the numbers the panel shows
 * (whole numbers, and distances with one decimal), and every form it has. */
function pluralForms(lang) {
  const used = new Set();
  for (const digits of [0, 1]) {
    const rules = new Intl.PluralRules(lang, { minimumFractionDigits: digits });
    for (let i = 0; i <= 2000; i++) used.add(rules.select(digits ? i / 10 : i));
  }
  return { used, all: new Set(new Intl.PluralRules(lang).resolvedOptions().pluralCategories) };
}

const vars = s => (String(s).match(/\{[a-z0-9]+\}|%[sd]/gi) || []).sort().join(" ");

function check({ order, langs }) {
  const errors = [];
  const en = langs.en;
  for (const code of order) {
    const L = langs[code], err = m => errors.push(`${code}.json: ${m}`);
    for (const k of META) if (typeof L.meta?.[k] !== "string" || !L.meta[k]) err(`meta.${k} is missing`);
    if (L.meta?.numberLocale) {
      try { new Intl.NumberFormat(L.meta.numberLocale); } catch { err(`meta.numberLocale "${L.meta.numberLocale}" isn't a locale`); }
    }
    const forms = pluralForms(code);
    for (const s of SECTIONS) {
      const mine = L[s] || {}, base = en[s] || {};
      for (const k of Object.keys(base)) if (!(k in mine)) err(`${s}.${k} is missing`);
      for (const k of Object.keys(mine)) if (!(k in base)) err(`${s}.${k} isn't in English (a typo, or a key that was removed?)`);
      for (const [k, v] of Object.entries(mine)) {
        const b = base[k];
        if (b === undefined) continue;
        if (isPlural(b)) {
          if (!isPlural(v)) { err(`${s}.${k} needs the plural forms ${[...forms.used].join(", ")}`); continue; }
          for (const f of forms.used) if (!(f in v)) err(`${s}.${k}.${f} is missing: ${code} uses it (${examples(code, f)})`);
          for (const f of Object.keys(v)) if (!forms.all.has(f)) err(`${s}.${k}.${f}: ${code} has no such plural form (it has ${[...forms.all].join(", ")})`);
          for (const [f, text] of Object.entries(v)) if (vars(text) !== vars(b.other)) err(`${s}.${k}.${f}: placeholders "${vars(text)}" differ from English "${vars(b.other)}"`);
        } else if (b && typeof b === "object") {
          if (!v || typeof v !== "object") { err(`${s}.${k} should be an object like English`); continue; }
          for (const kk of Object.keys(b)) if (!(kk in v)) err(`${s}.${k}.${kk} is missing`);
          for (const kk of Object.keys(v)) if (!(kk in b)) err(`${s}.${k}.${kk} isn't in English`);
          for (const kk of Object.keys(v)) if (kk in b && vars(v[kk]) !== vars(b[kk])) err(`${s}.${k}.${kk}: placeholders differ from English`);
        } else {
          if (typeof v !== "string") { err(`${s}.${k} should be text`); continue; }
          if (!v.trim()) err(`${s}.${k} is empty`);
          if (vars(v) !== vars(b)) err(`${s}.${k}: placeholders "${vars(v)}" differ from English "${vars(b)}"`);
        }
      }
    }
  }
  return errors;
}

/** "1, 21, 31" style examples of the numbers that take a plural form. */
function examples(lang, form) {
  const out = [];
  for (const digits of [0, 1]) {
    const rules = new Intl.PluralRules(lang, { minimumFractionDigits: digits });
    const fmt = new Intl.NumberFormat(lang, { minimumFractionDigits: digits });
    for (let i = 0; i <= 2000 && out.length < (digits ? 6 : 4); i++) {
      const n = digits ? i / 10 : i;
      if (rules.select(n) === form) out.push(fmt.format(n));
    }
  }
  return out.join(", ");
}

// ---------------------------------------------------------------- writers

const ident = k => (/^[A-Za-z_$][\w$]*$/.test(k) ? k : JSON.stringify(k));
const js = v => (typeof v === "string" ? JSON.stringify(v) : "{ " + Object.entries(v).map(([k, x]) => `${ident(k)}: ${JSON.stringify(x)}`).join(", ") + " }");
const pick = (o, keys) => Object.fromEntries(keys.map(k => [k, o[k]]));

/** The panel: STRINGS, LANG_NAMES and NUMBER_LOCALE inside ui/panel/panel.html. */
function panelBlock({ order, langs }) {
  const lines = [`  // <i18n> ${HEADER}`, "  const STRINGS = {"];
  for (const c of order) {
    const { meta, panel } = langs[c];
    lines.push(`    ${ident(c)}: {`);
    for (const [k, v] of Object.entries({ ...panel, m: meta.m, km: meta.km, decimal: meta.decimal })) lines.push(`      ${ident(k)}: ${js(v)},`);
    lines.push("    },");
  }
  lines.push("  };");
  lines.push(`  const LANG_NAMES = { ${order.map(c => `${ident(c)}: ${JSON.stringify(langs[c].meta.name)}`).join(", ")} };`);
  lines.push(`  const NUMBER_LOCALE = { ${order.map(c => `${ident(c)}: ${JSON.stringify(langs[c].meta.numberLocale)}`).join(", ")} };`);
  lines.push("  // </i18n>");
  return lines.join("\n");
}

function replaceBlock(file, text, block) {
  const a = text.indexOf("  // <i18n>"), b = text.indexOf("  // </i18n>");
  if (a < 0 || b < a) throw new Error(`${file}: the // <i18n> … // </i18n> markers are missing`);
  return text.slice(0, a) + block + text.slice(b + "  // </i18n>".length);
}

function vscodeCatalog({ order, langs }) {
  const obj = o => "{\n" + Object.entries(o).map(([k, v]) => `  ${ident(k)}: ${JSON.stringify(v)},`).join("\n") + "\n}";
  const out = [`// ${HEADER}`, ""];
  out.push(`const en = ${obj(langs.en.vscode)};`, "", "export type Key = keyof typeof en;", "");
  for (const c of order.slice(1)) out.push(`const ${c}: Record<Key, string> = ${obj(langs[c].vscode)};`, "");
  out.push(`export const catalogs: Record<string, Record<Key, string>> = { ${order.join(", ")} };`, "");
  out.push("/** The languages in the order of the language picker: English first, then by code. */");
  out.push(`export const LANGUAGES: readonly string[] = ${JSON.stringify(order)};`, "");
  out.push(`export const LANGUAGE_NAMES: Record<string, string> = { ${order.map(c => `${c}: ${JSON.stringify(langs[c].meta.name)}`).join(", ")} };`, "");
  out.push("/** How each language writes distances: the decimal separator and the units. */");
  out.push("export const UNITS: Record<string, { decimal: string; m: string; km: string }> = {");
  for (const c of order) out.push(`  ${c}: ${js(pick(langs[c].meta, ["decimal", "m", "km"]))},`);
  out.push("};", "");
  return out.join("\n");
}

function jetbrainsCatalog({ order, langs }) {
  const data = {
    _: HEADER,
    order,
    languages: Object.fromEntries(order.map(c => [c, { meta: langs[c].meta, texts: langs[c].jetbrains }])),
  };
  return JSON.stringify(data, null, 1) + "\n";
}

function luaCatalog({ order, langs }) {
  const s = v => JSON.stringify(v).replace(/\\u([0-9a-f]{4})/g, (_, h) => String.fromCodePoint(parseInt(h, 16)));
  const out = [`-- ${HEADER}`, "return {"];
  out.push(`  order = { ${order.map(s).join(", ")} },`);
  out.push("  languages = {");
  for (const c of order) {
    const { meta, neovim } = langs[c];
    out.push(`    ${c} = {`);
    out.push(`      meta = { ${META.map(k => `${k} = ${s(meta[k])}`).join(", ")} },`);
    out.push("      texts = {");
    for (const [k, v] of Object.entries(neovim)) out.push(`        ${k} = ${s(v)},`);
    out.push("      },", "    },");
  }
  out.push("  },", "}", "");
  return out.join("\n");
}

function goCatalog({ order, langs }) {
  const q = v => JSON.stringify(v);
  const out = [
    "// Code generated by scripts/i18n.mjs from i18n/*.json. DO NOT EDIT.",
    "// Edit i18n/<lang>.json, then run `task i18n`.",
    "",
    "package i18n",
    "",
    "// UILocales are the languages the panel and the IDE plugins are translated",
    "// into, English first. They count as available even before every route is",
    "// translated: route texts fall back to English.",
    `var UILocales = []string{${order.map(q).join(", ")}}`,
    "",
    "// Units says how each UI language writes a distance.",
    "var Units = map[string]Unit{",
  ];
  for (const c of order) {
    const m = langs[c].meta;
    out.push(`\t${q(c)}: {Decimal: ${q(m.decimal)}, M: ${q(m.m)}, KM: ${q(m.km)}},`);
  }
  out.push("}", "");
  return out.join("\n");
}

function nlsFiles({ order, langs }) {
  return Object.fromEntries(order.map(c => [`plugins/vscode/package.nls${c === "en" ? "" : "." + c}.json`, JSON.stringify(langs[c].commands, null, 2) + "\n"]));
}

function outputs(data) {
  const panelFile = "ui/panel/panel.html";
  const panel = fs.readFileSync(path.join(root, panelFile), "utf8");
  return {
    [panelFile]: replaceBlock(panelFile, panel, panelBlock(data)),
    "plugins/vscode/src/i18n.catalog.ts": vscodeCatalog(data),
    ...nlsFiles(data),
    "plugins/jetbrains/src/main/resources/i18n.json": jetbrainsCatalog(data),
    "plugins/neovim/lua/commit-hike/i18n.lua": luaCatalog(data),
    "core/internal/i18n/languages.go": goCatalog(data),
  };
}

// ---------------------------------------------------------------- new language

function startLanguage(code, { langs }) {
  if (!isLang(code)) throw new Error(`"${code}" isn't a language code: use two or three small letters, like cs`);
  const file = path.join(DIR, code + ".json");
  if (fs.existsSync(file)) throw new Error(`i18n/${code}.json already exists`);
  const forms = pluralForms(code);
  const en = langs.en, out = { meta: { name: "", numberLocale: code, decimal: en.meta.decimal, m: en.meta.m, km: en.meta.km } };
  for (const s of SECTIONS) {
    out[s] = {};
    for (const [k, v] of Object.entries(en[s])) {
      out[s][k] = isPlural(v) ? Object.fromEntries([...forms.used].map(f => [f, v[f] ?? v.other])) : v;
    }
  }
  fs.writeFileSync(file, JSON.stringify(out, null, 2) + "\n");
  console.log(`Created i18n/${code}.json from English. Translate every text, fill in meta.name (the language's own name), meta.numberLocale (like cs-CZ),`);
  console.log(`meta.decimal ("," or ".") and the units, then run: task i18n:check && task i18n`);
  console.log(`\nPlural forms in ${code} (kmWord, mWord, days, commitsN):`);
  for (const f of forms.used) console.log(`  ${f.padEnd(6)} ${examples(code, f)}`);
}

// ---------------------------------------------------------------- main

const args = process.argv.slice(2);
try {
  if (args[0] === "--new") {
    startLanguage(args[1], load());
    process.exit(0);
  }
  const data = load();
  const errors = check(data);
  if (errors.length) {
    console.error(`i18n: ${errors.length} problem${errors.length === 1 ? "" : "s"}:\n  ` + errors.join("\n  "));
    process.exit(1);
  }
  const files = outputs(data);
  if (args[0] === "--check") {
    const stale = Object.entries(files).filter(([f, text]) => !fs.existsSync(path.join(root, f)) || fs.readFileSync(path.join(root, f), "utf8") !== text).map(([f]) => f);
    if (stale.length) {
      console.error("i18n: generated files are out of date, run `task i18n`:\n  " + stale.join("\n  "));
      process.exit(1);
    }
    console.log(`i18n: ${data.order.length} languages (${data.order.join(", ")}), every text in place, generated files up to date`);
  } else {
    let n = 0;
    for (const [f, text] of Object.entries(files)) {
      const p = path.join(root, f);
      if (fs.existsSync(p) && fs.readFileSync(p, "utf8") === text) continue;
      fs.writeFileSync(p, text);
      console.log("wrote " + f);
      n++;
    }
    console.log(`i18n: ${data.order.join(", ")}; ${n} file${n === 1 ? "" : "s"} written`);
  }
} catch (e) {
  console.error("i18n: " + e.message);
  process.exit(1);
}
